import { sendInvoiceReminder } from "../property-cron";

const now = new Date("2026-06-15T10:00:00Z");

it("rejects a paid invoice", async () => {
  (storage.getInvoiceRentRequest as jest.Mock).mockResolvedValue({ id: "i1", status: "paid" });
  const r = await sendInvoiceReminder("i1", "http://x", now);
  expect(r).toMatchObject({ ok: false, reason: "not_payable" });
