  (storage.getInvoiceRentRequest as jest.Mock).mockResolvedValue({
    id: "i1", status: "overdue", lastReminderSentAt: new Date("2026-06-15T09:58:00Z"),
  });
  const r = await sendInvoiceReminder("i1", "http://x", now);
  expect(r.ok).toBe(false);
  expect(r.reason).toBe("cooldown");
